SELECT p.id, p.slug, c.iso_code, p.language, f.id AS feed_id FROM publishers p JOIN countries c ON c.id = p.country_id
  JOIN feeds f ON f.publisher_id = p.id WHERE p.slug IN ('fiji-one-news','islands-business','island-sun','sibc','vbtc','despacho-505','divergentes','la-hora-gt','prensa-comunitaria','hondudiario','contra-corriente','en-segundos','revista-factum','el-nuevo-diario-do','eldinero','alterpresse','juno7','rezo-nodwes','the-gleaner','jis-jamaica') ORDER BY p.id;
SELECT p.slug, e.classification_tags, left(e.historical_context, 60) FROM editorial_profiles e JOIN publishers p ON p.id = e.publisher_id
  WHERE p.slug IN ('rezo-nodwes', 'divergentes', 'sibc') ORDER BY 1;
COMMIT;
